mapper.select:
SELECT -- 订单标识 km.PRODUCTION_ORDER_NO, km.ASSEMBLY_MATERIAL_NO, km.MAIN_MATERIAL_DESC, km.ORDER_MESSAGE, -- 计划信息 km.SCHEDULED_DATE, km.PRODUCTION_WORKSHOP, km.SCHEDULED_QUANTITY, -- 组件信息 km.COMPONENT_MATERIAL_NO, km.COMPONENT_DESC, km.UNIT_USAGE, km.REQUIRED_QTY, -- 库存 km.STOCK_TOMORROW, km.STOCK_DAY_AFTER_TOMORROW, km.STOCK_THIRD_DAY, km.STOCK_QUANTITY, -- 齐套分析 km.SHORTAGE_QTY, km.OPEN_QUANTITY, km.OUTBOUND_QTY, km.COMPLETABLE_SETS, km.KITTING_STATUS, -- 父订单（总成自己是自己的父订单） km.PRODUCTION_ORDER_NO as PARENT_ORDER_NO, km.ASSEMBLY_KITTING_STATUS, KM.OPEN_FLAG FROM KITTING_MAIN km WHERE 1=1
AND km.PRODUCTION_ORDER_NO = #{params.productionOrderNo}
AND km.ASSEMBLY_MATERIAL_NO = #{params.assemblyMaterialNo}
AND km.COMPONENT_MATERIAL_NO = #{params.componentMaterialNo}
AND km.MAIN_MATERIAL_DESC LIKE '%' || #{params.mainMaterialDesc} || '%'
AND km.PRODUCTION_WORKSHOP = #{params.productionWorkshop}
AND km.SCHEDULED_DATE BETWEEN #{params.scheduledDate[0]} AND #{params.scheduledDate[1]}
AND km.SCHEDULED_DATE = #{params.scheduledDate[0]}
UNION ALL SELECT -- 订单标识 ks.PRODUCTION_ORDER_NO, ks.ASSEMBLY_MATERIAL_NO, ks.MAIN_MATERIAL_DESC, ks.ORDER_MESSAGE, -- 计划信息 ks.SCHEDULED_DATE, ks.PRODUCTION_WORKSHOP, ks.SCHEDULED_QUANTITY, -- 组件信息 ks.COMPONENT_MATERIAL_NO, ks.COMPONENT_DESC, ks.UNIT_USAGE, ks.REQUIRED_QTY, -- 库存 ks.STOCK_TOMORROW, ks.STOCK_DAY_AFTER_TOMORROW, ks.STOCK_THIRD_DAY, ks.STOCK_QUANTITY, -- 齐套分析 ks.SHORTAGE_QTY, ks.OPEN_QUANTITY, ks.OUTBOUND_QTY, ks.COMPLETABLE_SETS, ks.KITTING_STATUS, -- 父订单（绑定的总成） ks.PARENT_ORDER_NO, ks.ASSEMBLY_KITTING_STATUS, ks.OPEN_FLAG FROM KITTING_SUB ks WHERE 1=1
AND ks.PRODUCTION_ORDER_NO = #{params.productionOrderNo}
AND ks.ASSEMBLY_MATERIAL_NO = #{params.assemblyMaterialNo}
AND ks.COMPONENT_MATERIAL_NO = #{params.componentMaterialNo}
AND ks.MAIN_MATERIAL_DESC LIKE '%' || #{params.mainMaterialDesc} || '%'
AND ks.PRODUCTION_WORKSHOP = #{params.productionWorkshop}
AND ks.SCHEDULED_DATE BETWEEN #{params.scheduledDate[0]} AND #{params.scheduledDate[1]}
AND ks.SCHEDULED_DATE = #{params.scheduledDate[0]}
